def compute(vars):
    securities = vars["v1"]
    price_per_security = vars["v2"]
    total_value_dollars = securities * price_per_security
    value_millions = total_value_dollars / 1_000_000

    return {
        "value": value_millions,
        "trace": {
            "securities": securities,
            "price_per_security": price_per_security,
            "total_value_dollars": total_value_dollars,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency",
            },
        },
    }
